import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"Teacher Dashboard -> Profile Setting (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/teacher-dashboard/profile-setting.md","filePath":"modules/teacher-dashboard/profile-setting.md"}'),i={name:"modules/teacher-dashboard/profile-setting.md"};function d(l,e,s,n,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="teacher-dashboard-profile-setting-deep" tabindex="-1">Teacher Dashboard -&gt; Profile Setting (deep) <a class="header-anchor" href="#teacher-dashboard-profile-setting-deep" aria-label="Permalink to &quot;Teacher Dashboard -&gt; Profile Setting (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>teacher-dashboard</code><br><strong>Feature:</strong> <code>profile-setting</code><br><strong>Route:</strong> <code>/teacher-dashboard/settings</code><br><strong>Nested route:</strong> <code>/teacher-dashboard/settings/edit-profile</code></p><p>This is the instructor settings shell. It loads the teacher profile, renders the profile summary header, exposes the tabbed settings areas, and routes into the edit-profile page.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show core instructor profile data in one place.</li><li>Provide access to tabbed subfeatures: <ul><li>Documents</li><li>Price management</li><li>Availability &amp; calendar</li><li>Ratings &amp; scores</li><li>Payment management</li></ul></li><li>Route to a dedicated edit-profile page.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/teacher-dashboard/profileSetting.tsx</code></td><td>Main settings shell</td><td>Calls <code>GET_TEACHER_PROFILE</code>; owns local tab state and the edit-profile route handoff.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/editProfile.tsx</code></td><td>Profile edit page</td><td>Uses teacher profile query + update mutation + upload URL flow.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/DocumentsTab.tsx</code></td><td>Settings tab</td><td>Receives documents from the shell and delegates upload/update flow.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/TariffTab.tsx</code></td><td>Settings tab</td><td>Handles price/package settings.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/AvailabilityTab.tsx</code></td><td>Settings tab</td><td>Handles calendar availability.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/RatingsTab.tsx</code></td><td>Settings tab</td><td>Shows reviews/ratings.</td></tr><tr><td><code>Frontend/src/pages/private/teacher-dashboard/tabs/PaymentTab.tsx</code></td><td>Settings tab</td><td>Shows Stripe onboarding/payment setup state.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="get-teacher-profile" tabindex="-1"><code>GET_TEACHER_PROFILE</code> <a class="header-anchor" href="#get-teacher-profile" aria-label="Permalink to &quot;`GET_TEACHER_PROFILE`&quot;">​</a></h3><ul><li>Files: <ul><li><code>Frontend/src/pages/private/teacher-dashboard/profileSetting.tsx</code></li><li><code>Frontend/src/pages/private/teacher-dashboard/editProfile.tsx</code></li><li><code>Frontend/src/layouts/TeacherLayout.tsx</code></li><li><code>Frontend/src/pages/private/teacher-dashboard/tabs/PaymentTab.tsx</code></li></ul></li><li>Source file: <code>Frontend/src/graphql/mutations/profile.ts</code></li><li>Query field: <code>teacherProfile</code></li><li>Used for: <ul><li>header/profile summary in settings shell</li><li>Stripe onboarding state</li><li>edit-profile initial values</li><li>layout-level readiness checks</li></ul></li></ul><h3 id="edit-profile-operations" tabindex="-1">Edit-profile operations <a class="header-anchor" href="#edit-profile-operations" aria-label="Permalink to &quot;Edit-profile operations&quot;">​</a></h3><ul><li><code>UPDATE_TEACHER_PROFILE</code><ul><li>file: <code>Frontend/src/graphql/mutations/profile.ts</code></li><li>used by <code>editProfile.tsx</code></li></ul></li><li><code>GENERATE_UPLOAD_URL</code><ul><li>file: <code>Frontend/src/graphql/mutations/auth.ts</code></li><li>used indirectly through <code>useFileUpload</code> in <code>editProfile.tsx</code></li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs.js</code></li><li>Relevant query: <ul><li><code>teacherProfile: InstructorProfile</code></li></ul></li><li>Relevant mutation: <ul><li><code>updateTeacherProfile(input: UpdateInstructorProfileInput!): InstructorProfile</code></li></ul></li><li>Relevant types: <ul><li><code>InstructorProfile</code></li><li><code>UpdateInstructorProfileInput</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>Files: <ul><li><code>server/src/graphql/resolvers.js</code></li><li><code>server/src/graphql/resolvers/tariff.resolver.js</code></li></ul></li><li>Relevant resolvers: <ul><li><code>Query.teacherProfile</code><ul><li>loads instructor profile</li><li>computes <code>reviewRating</code>, <code>reviewsCount</code></li><li>exposes Stripe onboarding/account snapshots and financial status</li></ul></li><li><code>Mutation.updateTeacherProfile</code><ul><li>updates instructor profile fields</li><li>used by the edit-profile page</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/User.js</code></td><td>Stores instructor profile data and Stripe state</td></tr><tr><td><code>server/src/schemas/validation.js</code></td><td>Validates instructor profile updates</td></tr><tr><td><code>server/src/services/stripeService.js</code></td><td>Supplies Stripe snapshot/account fields surfaced in profile</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Instructor opens <code>/teacher-dashboard/settings</code>.</li><li><code>profileSetting.tsx</code> loads <code>teacherProfile</code>.</li><li>The page builds the profile header cards and document list from the response.</li><li>Tab state is local inside the settings shell, so changing tabs does not change the URL.</li><li>Clicking Edit Profile navigates to <code>/teacher-dashboard/settings/edit-profile</code>.</li><li>The settings shell renders <code>&lt;Outlet /&gt;</code> when the nested edit-profile route is active.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>Only <code>edit-profile</code> is route-driven; all other settings sections are tab-driven inside the same page.</li><li>This doc covers the shell and shared profile query. Each tab has its own deeper doc in this folder.</li></ul>',23)])])}const f=t(i,[["render",d]]);export{u as __pageData,f as default};
